local seat_uid= -1
local StakeScene = class("StakeScene")
local position ={}
local gold = 0
local chip_position = {}
function StakeScene:initData()
    for i = 1, TOTAL_PLAYERNUM do
        local panel = self.SG_LIST_PANEL:getChildByName("no_panel_"..i)
        local text_my_total =panel:getChildByName("text_my_total")
        local text_total =panel:getChildByName("text_total")
        text_my_total:setString(0)
        text_total:setString(0)
        local btn_panel = panel:getChildByName("btn_panel")
        btn_panel:getChildByName("image"):setVisible(false)
        local user_head = panel:getChildByName("user_head")
        user_head:loadTexture(TpackageName.."/images/stake/kongtouxaing.png")
    end
    self.SG_DETAIL_PANEL:getChildByName("content_lv"):removeAllItems()
end
function StakeScene:showImage(playerType,flag)
    dump(playerType,"playerType")
    for i = 1, TOTAL_PLAYERNUM do
        local panel = self.SG_LIST_PANEL:getChildByName("no_panel_"..i)
        local btn_panel = panel:getChildByName("btn_panel")
        if playerType == i then
            btn_panel:getChildByName("image"):setVisible(true)
        else
            btn_panel:getChildByName("image"):setVisible(false)
        end
    end


end
function StakeScene:init()
    self:initPosition()
    --if self.STAKESCENE == nil or tolua.isnull(self.STAKESCENE) then
	if TOTAL_PLAYERNUM == 12 then
        self.STAKESCENE = cc.CSLoader:createNode("sangong/csb/stakeScene12.csb")
	else
        self.STAKESCENE = cc.CSLoader:createNode("sangong/csb/stakeScene.csb")
	end
    SanGongPanel:addChild(self.STAKESCENE,999)
        --self.STAKESCENE:addTo(self,999)
    --end
    self.SG_LIST_PANEL = self.STAKESCENE:getChildByName("list_panel")
    self.SG_DETAIL_PANEL = self.STAKESCENE:getChildByName("detail_panel")
    self.SG_DETAIL_PANEL:setVisible(false)
    self.SG_LIST_PANEL:setVisible(false)
    self.SG_DETAIL_PANEL:retain()
    self.btn_back =  self.SG_DETAIL_PANEL:getChildByName("btn_back")
    self:initData()

    local foot_panel =self.SG_LIST_PANEL:getChildByName("foot_panel")
    self.gold_panel = self.SG_LIST_PANEL:getChildByName("gold_panel")
    local chip_bg = foot_panel:getChildByName("chip_bg")
    if chip_bg then
        self.text_gold = chip_bg:getChildByName("text_gold")
    end
    self.btn_close = foot_panel:getChildByName("btn_close")
    self.btn_confirm = foot_panel:getChildByName("btn_confirm")
    self.btn_clear = foot_panel:getChildByName("btn_clear")
    self.btn_allin = foot_panel:getChildByName("btn_allin")
    local function touchButtonEvent(sender,event)
        --触摸开始
        if event == TOUCH_EVENT_BEGAN then
            sender:setScale(0.9)
        end

        --触摸取消
        if event == TOUCH_EVENT_CANCELED then
            sender:setScale(1.0)
        end

        --触摸结束
        if event == TOUCH_EVENT_ENDED then
            sender:setScale(1.0)
            if sender.type == 1 then
                if self.text_gold then
                    local number = self.text_gold:getString()
                    dump(number,"number")
                    dump(seat_uid,"seat_uid")
                    local value = 0
                    if isRide then
                        value = number*100
                    else
                        value = number
                    end
                    SanGongSendHandle:CLIENT_CMD_YA(seat_uid,value)
                end
            elseif sender.type == 2 then
                gold = sender.gold
                chip_position = sender:getPosition()
                self.text_gold:setString(SanGongUtils:goldMath(sender.gold))
            elseif sender.type == 3 then
                self:closeStakeScene()
            elseif sender.type == 4 then
                self.text_gold:setString(0)
            elseif sender.type == 5 then
                self.SG_DETAIL_PANEL:setVisible(false)
                IS_DETAIL_STOP = true
                self:clearDetailList()
            elseif sender.type == 6 then
                local gold = math.floor(SANGONG_USERINFO_TABLE[USER_INFO["uid"]].gold)
                self.text_gold:setString(gold)
            end

        end
    end
    dump(GAME_CHIP_CONFIG,"GAME_CHIP_CONFIG")
    for k,v in ipairs(GAME_CHIP_CONFIG) do
        dump(v,"GAME_CHIP_CONFIG")
        local btn_chip = foot_panel:getChildByName("btn_chip_"..k)
        if k == 1 then
            gold = v
            chip_position = btn_chip:getPosition()
        end
        local chp =  SanGongUtils:goldMath(v)
        local text = SanGongUtils:getChipBtnText(chp)
        text:setPosition(cc.p(btn_chip:getContentSize().width/2 -2,btn_chip:getContentSize().height/2 +5))
        btn_chip:addChild(text)
        btn_chip.gold = v
        btn_chip.type =2
        btn_chip:addTouchEventListener(touchButtonEvent)
    end
    self.btn_confirm.type = 1
    self.btn_confirm:addTouchEventListener(touchButtonEvent)
    self.btn_close.type = 3
    self.btn_close:addTouchEventListener(touchButtonEvent)
    self.btn_clear.type = 4
    self.btn_clear:addTouchEventListener(touchButtonEvent)
    self.btn_back.type = 5
    self.btn_back:addTouchEventListener(touchButtonEvent)
    self.btn_allin.type =6
    self.btn_allin:addTouchEventListener(touchButtonEvent)
    self.STAKESCENE:setVisible(false)

end
function StakeScene:closeStakeScene()
    self.STAKESCENE:setVisible(false)
    self:initData()
end
function StakeScene:showOnStake(pack)
    local seat = pack.seat+1
    if self.SG_LIST_PANEL == nil or tolua.isnull(self.SG_LIST_PANEL) then
        self:init()
    end
    local panel =self.SG_LIST_PANEL:getChildByName("no_panel_"..seat)
    if panel then
        local text_my_total =panel:getChildByName("text_my_total")
        local text_total =panel:getChildByName("text_total")
        text_my_total:setString(0)
        text_total:setString(0)
        local user_head = panel:getChildByName("user_head")
        local btn_panel = panel:getChildByName("btn_panel")
        local text_details = panel:getChildByName("detail_panel")

        local userInfo = SANGONG_USERINFO_TABLE[pack.uid]

        require("hall.GameCommon"):getUserHead(userInfo["icon_url"], userInfo["uid"], userInfo["sex"], user_head, 78, false,userInfo["nick"])
        if btn_panel then
            btn_panel.seat = pack.seat
            btn_panel.uid = pack.uid
            btn_panel:addTouchEventListener(function (sender,event)
                if event == TOUCH_EVENT_ENDED then
                    seat_uid =  sender.uid
                    SanGongSendHandle:CLIENT_CMD_YA(seat_uid,gold)
                    local playerType = SANGONG_SEAT_TABLE[sender.uid]+1
                    self:showImage(playerType,true)
                    dump(seat_uid,"no_panel_")
                end
            end)
        end
        if text_details then
            text_details.seat = pack.seat
            text_details:addTouchEventListener(function (sender,event)
                if event == TOUCH_EVENT_ENDED then
                    SanGongSendHandle:CLIENT_CMD_REQ_YAZHU_DETAILS(sender.seat)
                end
            end)
        end
    end

end
function StakeScene:showStakeScene(dataList)
    if self.STAKESCENE == nil or tolua.isnull(self.STAKESCENE) or tolua.isnull(self.SG_LIST_PANEL)  then
        self:init()
    end
    print("showStakeScene")
    self.STAKESCENE:setVisible(true)
    self.SG_DETAIL_PANEL:setVisible(false)
    self.SG_LIST_PANEL:setVisible(true)
    self.STAKESCENE:setLocalZOrder(9999)
    seat_uid = -1
    for i,v in pairs(dataList) do
        local index = SANGONG_SEAT_TABLE[v.uid]+1
        local panel =self.SG_LIST_PANEL:getChildByName("no_panel_"..index)

        if i == 1 then
            self:showImage(index,true)
            seat_uid =  v.uid
        end
        local text_my_total =panel:getChildByName("text_my_total")
        local text_total =panel:getChildByName("text_total")
        text_my_total:setString(SanGongUtils:goldMath(v.my_total))
        text_total:setString(SanGongUtils:goldMath(v.total))
        local user_head = panel:getChildByName("user_head")
        local btn_panel = panel:getChildByName("btn_panel")
        local text_details = panel:getChildByName("detail_panel")

        local userInfo = SANGONG_USERINFO_TABLE[v.uid]

        require("hall.GameCommon"):getUserHead(userInfo["icon_url"], userInfo["uid"], userInfo["sex"], user_head, 78, false,userInfo["nick"])
        if btn_panel then
            btn_panel.seat = v.seat
            btn_panel.uid = v.uid
            btn_panel:addTouchEventListener(function (sender,event)
                if event == TOUCH_EVENT_ENDED then
                    if SANGONG_SEAT_TABLE[sender.uid] then
                        seat_uid =  sender.uid
                        SanGongSendHandle:CLIENT_CMD_YA(seat_uid,gold)
                        local playerType = SANGONG_SEAT_TABLE[seat_uid]+1
                        self:showImage(playerType,true)
                        dump(seat_uid,"no_panel_")
                    end

                end
            end)
        end
        if text_details then
            text_details.seat = v.seat
            text_details:addTouchEventListener(function (sender,event)
                if event == TOUCH_EVENT_ENDED then
                    dump("111111111111111111111111111111111111")
                    IS_DETAIL_STOP = false
                    SanGongSendHandle:CLIENT_CMD_REQ_YAZHU_DETAILS(sender.seat)
                end
            end)
        end

    end

end

function StakeScene:showDetail(pack)
    --self.SG_DETAIL_PANEL:getChildByName("content_lv")
    if self.SG_DETAIL_PANEL == nil or tolua.isnull(self.SG_DETAIL_PANEL) then
        self:init()
    end
    local content_lv =  self.SG_DETAIL_PANEL:getChildByName("content_lv")
    --content_lv:removeAllItems()
    local index = 1
    local count = 0
    local panel
    for i,v in pairs(pack.countArr) do
        local item
        local  index = (count % 4)
        if index == 0 then
            panel =  self.SG_DETAIL_PANEL:getChildByName("panel"):clone()
            item = panel:getChildByName("item_"..index)
            content_lv:pushBackCustomItem(panel)
        else
            item = panel:getChildByName("item_"..index)
        end
        --if index == 4 or index ==1 then
        --    panel =  self.SG_DETAIL_PANEL:getChildByName("panel"):clone()
        --    item = panel:getChildByName("item_"..index)
        --    content_lv:pushBackCustomItem(panel)
        --    index = 1
        --else
        --    item = panel:getChildByName("item_"..index)
        --end
        if item then
            item:setVisible(true)
        end
        local score = item:getChildByName("score")
        local nick = item:getChildByName("nick")
        local no = item:getChildByName("no")
        local time_text = item:getChildByName("time_text")
        nick:setString(SanGongUtils:formatNick(v.nickName or "", 4))
        no:setString(v.no)
        time_text:setString(v.time)
        score:setString(SanGongUtils:goldMath(v.zhu))

        local head = display.newSprite("sangong/images/over/kong.png")
        head:addTo(item)
        head:setPosition(41.84, 41.84)
        local userinfo = {
            icon_url = v.portrait
        }
        local head_info = {}
        head_info["icon_url"] =   v.portrait or DefaultHead_filePath
        head_info["uid"] = v.uid
        head_info["sex"] = v["sex"] or 1
        head_info["sp"] = head
        head_info["size"] = 65
        head_info["touchable"] = 0
        head_info["use_sharp"] = 1
        require("hall.GameCommon"):setPlayerHead(head_info, head, 65)

        count = count + 1
    end
    self.SG_DETAIL_PANEL:setVisible(true)
end
