function StakeScene:updateStakeGold(pack)
    if self.SG_LIST_PANEL == nil or tolua.isnull(self.SG_LIST_PANEL) then
        self:init()
    end
    local playerType = SANGONG_SEAT_TABLE[pack.desUid]+1
    local panel =self.SG_LIST_PANEL:getChildByName("no_panel_"..playerType)
    local text_my_total =panel:getChildByName("text_my_total")
    local text_total =panel:getChildByName("text_total")
    text_total:setString(SanGongUtils:goldMath(pack.total))
    local rand_x = math.random(position[playerType].rand_x["x_1"],position[playerType].rand_x["x_2"])
    local rand_y = math.random(position[playerType].rand_y["y_1"],position[playerType].rand_y["y_2"])
    local btn_chip = SanGongUtils:getChipBtnNew(SanGongUtils:goldMath(pack.chip))
    if pack.uid == USER_INFO["uid"] then
        text_my_total:setString(SanGongUtils:goldMath(pack.myTotal))
        btn_chip:setPosition(cc.p(chip_position.x+1620,chip_position.y))
        self.gold_panel:addChild(btn_chip)
        local move = cc.MoveTo:create(0.1,cc.p(rand_x,rand_y))
        btn_chip:runAction(move)
    else
        btn_chip:setPosition(cc.p(rand_x,rand_y))
        self.gold_panel:addChild(btn_chip)
    end


end
function StakeScene:clearGoldPanel()
    self.gold_panel:removeAllChildren()
end

function StakeScene:clearDetailList()
    if self.SG_DETAIL_PANEL then
        local content_lv =  self.SG_DETAIL_PANEL:getChildByName("content_lv")
        if content_lv then
            IS_DETAIL_STOP = true
            content_lv:removeAllItems()
        end

    end

end
return StakeScene